// lib/data/posts.ts — the data-access layer
import { auth } from '@/auth';

export async function getPosts() {
  const session = await auth();
  if (!session) throw new Error('Unauthorized');
  const res = await fetch(`${process.env.API}/posts?tenant=${session.user.tenantId}`, {
    next: { tags: ['posts'], revalidate: 60 },
  });
  return res.json() as Promise<Post[]>;
}

// app/(app)/posts/actions.ts — the mutation
'use server';
import { revalidateTag } from 'next/cache';
import { auth } from '@/auth';

export async function createPost(input: { title: string }) {
  const session = await auth();
  if (!session) throw new Error('Unauthorized');
  await db.post.create({ data: { ...input, tenantId: session.user.tenantId } });
  revalidateTag('posts'); // refresh exactly the cached reads tagged 'posts'
  return { ok: true };
}
